INSERT INTO scenario_gaps (project_id, kind, detector, class, key, title, evidence, factors, status, created_at, updated_at, score) VALUES (1, 'gap', 'declared-never-hit', 'blind-spot', 'route:DELETE /api/orders/:id', 'Declared route DELETE /api/orders/:id — never reached', '["Declared in OpenAPI · 0 tests in 30 runs · documents 200, 401, 404, 409 — observed reach."]', '{"churn":0.4,"age":0.5,"escapeHistory":0.1,"priority":0.4}', 'open', 1745569800000, 1745569800000, 0.2093);
INSERT INTO scenario_gaps (project_id, kind, detector, class, key, title, evidence, factors, score, test_case_id, status, created_at, updated_at) VALUES (1, 'finding', 'not-handled', 'unhandled', 'dependency:payments-svc @ POST /api/orders', 'payments-svc (via POST /api/orders): unhandled failure', '["A server probe made payments-svc (via POST /api/orders) fail; the application did not handle it (should complete checkout with credit card) — an error-state scenario is missing."]', '{"churn":0.1,"age":0.1,"escapeHistory":0.1,"priority":0.3}', 0.3, 1, 'open', 1745569800000, 1745569800000);
INSERT INTO scenario_gaps (project_id, kind, detector, class, key, title, evidence, factors, status, created_at, updated_at, score) VALUES (1, 'gap', 'unprobed-dependency', 'false-comfort', 'dependency:payments-svc', 'payments-svc is never probed', '["Called by 1 route · no probe has checked what happens when it fails — schedule a dependency probe."]', '{"churn":0.1,"age":0.1,"escapeHistory":0.1,"priority":0.1}', 'open', 1745569800000, 1745569800000, 0.04);
