-- Files (screenshot/trace/video attachments — reference test_runs_cases, so must come after)

-- Entity links (may reference test_runs_cases, so must come after)

-- Network requests (child table, references test_runs_cases)

-- Quarantined tests (references test_cases)

-- Locator healing snapshots (references test_cases)

-- Code reach (references test_cases and test_runs)

-- Probe ledger (Test Map, checked axis)

-- Flake-lab experiments and their arms (references test_cases)

-- Function catalog (page-object methods and helpers the suite owns)

-- Feature graph nodes (Test Map)

-- Feature graph edges (references nothing by FK; endpoints are typed keys)

-- Scenario gaps (references test_cases; test_run_id is not an FK)

-- ── Rebase every timestamp to load time (see generator for rationale) ──────
CREATE TEMP TABLE _rebase AS SELECT (CAST(strftime('%s', 'now') AS INTEGER) - 1745572680) AS delta_sec;

-- Second-precision timestamp columns
UPDATE tags SET created_at = created_at + (SELECT delta_sec FROM _rebase), updated_at = updated_at + (SELECT delta_sec FROM _rebase);
UPDATE projects SET created_at = created_at + (SELECT delta_sec FROM _rebase), updated_at = updated_at + (SELECT delta_sec FROM _rebase);
UPDATE markers SET occurred_at = occurred_at + (SELECT delta_sec FROM _rebase), created_at = created_at + (SELECT delta_sec FROM _rebase), updated_at = updated_at + (SELECT delta_sec FROM _rebase);
UPDATE project_url_patterns SET created_at = created_at + (SELECT delta_sec FROM _rebase) * 1000, updated_at = updated_at + (SELECT delta_sec FROM _rebase) * 1000;
UPDATE bug_reports SET created_at = created_at + (SELECT delta_sec FROM _rebase), updated_at = updated_at + (SELECT delta_sec FROM _rebase);
UPDATE bug_reproductions SET created_at = created_at + (SELECT delta_sec FROM _rebase);
UPDATE users SET created_at = created_at + (SELECT delta_sec FROM _rebase), updated_at = updated_at + (SELECT delta_sec FROM _rebase);
UPDATE app_settings SET updated_at = updated_at + (SELECT delta_sec FROM _rebase);
UPDATE test_selections SET created_at = created_at + (SELECT delta_sec FROM _rebase), updated_at = updated_at + (SELECT delta_sec FROM _rebase);
UPDATE test_suites SET created_at = created_at + (SELECT delta_sec FROM _rebase), updated_at = updated_at + (SELECT delta_sec FROM _rebase);
UPDATE test_cases SET created_at = created_at + (SELECT delta_sec FROM _rebase), updated_at = updated_at + (SELECT delta_sec FROM _rebase);
UPDATE test_runs SET start_time = start_time + (SELECT delta_sec FROM _rebase), created_at = created_at + (SELECT delta_sec FROM _rebase), updated_at = updated_at + (SELECT delta_sec FROM _rebase), kept_at = kept_at + (SELECT delta_sec FROM _rebase);
UPDATE files SET created_at = created_at + (SELECT delta_sec FROM _rebase);
UPDATE case_payloads SET created_at = created_at + (SELECT delta_sec FROM _rebase);
UPDATE failure_clusters SET created_at = created_at + (SELECT delta_sec FROM _rebase), updated_at = updated_at + (SELECT delta_sec FROM _rebase), fix_landed_at = fix_landed_at + (SELECT delta_sec FROM _rebase);
UPDATE test_run_resource_reports SET updated_at = updated_at + (SELECT delta_sec FROM _rebase);
UPDATE resource_findings SET first_seen_at = first_seen_at + (SELECT delta_sec FROM _rebase), last_seen_at = last_seen_at + (SELECT delta_sec FROM _rebase), created_at = created_at + (SELECT delta_sec FROM _rebase), updated_at = updated_at + (SELECT delta_sec FROM _rebase), fixed_at = fixed_at + (SELECT delta_sec FROM _rebase);
UPDATE quarantined_tests SET created_at = created_at + (SELECT delta_sec FROM _rebase), released_at = released_at + (SELECT delta_sec FROM _rebase);
UPDATE failure_diagnoses SET created_at = created_at + (SELECT delta_sec FROM _rebase), updated_at = updated_at + (SELECT delta_sec FROM _rebase);
UPDATE failure_diagnosis_versions SET created_at = created_at + (SELECT delta_sec FROM _rebase);
UPDATE cluster_merge_suggestions SET created_at = created_at + (SELECT delta_sec FROM _rebase), updated_at = updated_at + (SELECT delta_sec FROM _rebase);

-- Millisecond timestamp columns
UPDATE test_runs_cases SET started_at = started_at + (SELECT delta_sec FROM _rebase) * 1000, created_at = created_at + (SELECT delta_sec FROM _rebase) * 1000;
UPDATE network_requests SET start_time = start_time + (SELECT delta_sec FROM _rebase) * 1000;
UPDATE groups SET created_at = created_at + (SELECT delta_sec FROM _rebase) * 1000, updated_at = updated_at + (SELECT delta_sec FROM _rebase) * 1000;
UPDATE group_members SET created_at = created_at + (SELECT delta_sec FROM _rebase) * 1000;
UPDATE role_bindings SET created_at = created_at + (SELECT delta_sec FROM _rebase) * 1000;
UPDATE analytics_dashboards SET created_at = created_at + (SELECT delta_sec FROM _rebase) * 1000, updated_at = updated_at + (SELECT delta_sec FROM _rebase) * 1000, last_viewed_at = last_viewed_at + (SELECT delta_sec FROM _rebase) * 1000;
UPDATE entity_links SET created_at = created_at + (SELECT delta_sec FROM _rebase) * 1000, updated_at = updated_at + (SELECT delta_sec FROM _rebase) * 1000;
UPDATE locator_snapshots SET last_seen_at = last_seen_at + (SELECT delta_sec FROM _rebase) * 1000;
UPDATE handback_outcomes SET created_at = created_at + (SELECT delta_sec FROM _rebase) * 1000;
UPDATE code_reach SET last_seen_at = last_seen_at + (SELECT delta_sec FROM _rebase) * 1000;
UPDATE probes SET probed_at = probed_at + (SELECT delta_sec FROM _rebase) * 1000;
UPDATE flake_experiments SET created_at = created_at + (SELECT delta_sec FROM _rebase) * 1000, finished_at = finished_at + (SELECT delta_sec FROM _rebase) * 1000;
UPDATE test_functions SET created_at = created_at + (SELECT delta_sec FROM _rebase) * 1000, updated_at = updated_at + (SELECT delta_sec FROM _rebase) * 1000;
UPDATE graph_nodes SET last_seen_at = last_seen_at + (SELECT delta_sec FROM _rebase) * 1000, created_at = created_at + (SELECT delta_sec FROM _rebase) * 1000, pruned_at = pruned_at + (SELECT delta_sec FROM _rebase) * 1000;
UPDATE graph_edges SET last_seen_at = last_seen_at + (SELECT delta_sec FROM _rebase) * 1000, created_at = created_at + (SELECT delta_sec FROM _rebase) * 1000;
UPDATE scenario_gaps SET created_at = created_at + (SELECT delta_sec FROM _rebase) * 1000, updated_at = updated_at + (SELECT delta_sec FROM _rebase) * 1000, accepted_at = accepted_at + (SELECT delta_sec FROM _rebase) * 1000, covered_at = covered_at + (SELECT delta_sec FROM _rebase) * 1000, closed_at = closed_at + (SELECT delta_sec FROM _rebase) * 1000, snoozed_until = snoozed_until + (SELECT delta_sec FROM _rebase) * 1000;

-- ISO timestamps embedded in JSON columns
UPDATE test_runs SET metadata = json_set(metadata, '$.incident.decidedAt', strftime('%Y-%m-%dT%H:%M:%fZ', json_extract(metadata, '$.incident.decidedAt'), '+' || (SELECT delta_sec FROM _rebase) || ' seconds')) WHERE json_valid(metadata) AND json_extract(metadata, '$.incident.decidedAt') IS NOT NULL;

-- Millisecond timestamps embedded in JSON columns
UPDATE test_runs_cases SET steps = (SELECT json_group_array(CASE WHEN json_extract(value, '$.startTime') IS NOT NULL THEN json_set(value, '$.startTime', json_extract(value, '$.startTime') + (SELECT delta_sec FROM _rebase) * 1000) WHEN type IN ('object', 'array') THEN json(value) ELSE value END) FROM json_each(test_runs_cases.steps)) WHERE steps IS NOT NULL AND json_valid(steps);
UPDATE test_runs_cases SET step_events = (SELECT json_group_array(CASE WHEN json_extract(value, '$.startedAt') IS NOT NULL THEN json_set(value, '$.startedAt', json_extract(value, '$.startedAt') + (SELECT delta_sec FROM _rebase) * 1000) WHEN type IN ('object', 'array') THEN json(value) ELSE value END) FROM json_each(test_runs_cases.step_events)) WHERE step_events IS NOT NULL AND json_valid(step_events);
UPDATE test_runs_cases SET console_logs = (SELECT json_group_array(CASE WHEN json_extract(value, '$.timestamp') IS NOT NULL THEN json_set(value, '$.timestamp', json_extract(value, '$.timestamp') + (SELECT delta_sec FROM _rebase) * 1000) WHEN type IN ('object', 'array') THEN json(value) ELSE value END) FROM json_each(test_runs_cases.console_logs)) WHERE console_logs IS NOT NULL AND json_valid(console_logs);
UPDATE test_runs_cases SET dialogs = (SELECT json_group_array(CASE WHEN json_extract(value, '$.closedAt') IS NOT NULL THEN json_set(value, '$.closedAt', json_extract(value, '$.closedAt') + (SELECT delta_sec FROM _rebase) * 1000) WHEN type IN ('object', 'array') THEN json(value) ELSE value END) FROM json_each(test_runs_cases.dialogs)) WHERE dialogs IS NOT NULL AND json_valid(dialogs);
UPDATE test_runs_cases SET attempts = (SELECT json_group_array(CASE WHEN json_extract(value, '$.startedAt') IS NOT NULL THEN json_set(value, '$.startedAt', json_extract(value, '$.startedAt') + (SELECT delta_sec FROM _rebase) * 1000) WHEN type IN ('object', 'array') THEN json(value) ELSE value END) FROM json_each(test_runs_cases.attempts)) WHERE attempts IS NOT NULL AND json_valid(attempts);
UPDATE network_requests SET server_logs = (SELECT json_group_array(CASE WHEN json_extract(value, '$.timestamp') IS NOT NULL THEN json_set(value, '$.timestamp', json_extract(value, '$.timestamp') + (SELECT delta_sec FROM _rebase) * 1000) WHEN type IN ('object', 'array') THEN json(value) ELSE value END) FROM json_each(network_requests.server_logs)) WHERE server_logs IS NOT NULL AND json_valid(server_logs);
UPDATE test_run_resource_reports SET report = json_set(report, '$.timeline.startedAt', json_extract(report, '$.timeline.startedAt') + (SELECT delta_sec FROM _rebase) * 1000) WHERE json_valid(report) AND json_extract(report, '$.timeline.startedAt') IS NOT NULL;

DROP TABLE _rebase;

COMMIT;